  // ── /about — opening (origin + Star Wars crawl) ──
  'about.origin.title': 'L\'Origine',
  'about.origin.sub': 'Scorri e leggi',
  'about.origin.skip': 'o salta',
  'about.crawl.intro': 'Dieci anni fa, in un canile nel cuore dell\'Europa….',
  'about.crawl.episode': 'Episodio I',
  'about.crawl.faith': 'Una Nuova Fede',
  'about.crawl.p1':
    'Nel 2016, otto cuccioli neri arrivarono al canile, gettati via in un\'unica scatola. Sette trovarono una casa. Il più grande non lo voleva nessuno — aspettò un anno intero. Si chiamava Hekthor.',
  'about.crawl.p2':
    'Un giorno una coppia venne al canile per vedere Sindy, una piccola femmina bianca che volevano adottare. Per puro caso, Hekthor si trovava nel suo box in quel momento — il suo veniva appena pulito. L\'uomo, che era venuto solo per accompagnare e non aveva mai voluto un cane, si innamorò del cane nero che vedeva per la prima volta in assoluto.',
  'about.crawl.p3':
    'Una settimana dopo erano insieme, ed ebbe inizio una bellissima storia. Tutta la vita dell\'uomo cambiò, e col tempo capì una cosa: solo chi ha un cane, e sa cosa si prova davanti all\'amore di un cane, può davvero aiutare i cani in difficoltà.',
  'about.crawl.p4':
    'E così nacque l\'Heroglyph — un simbolo destinato a unire gli amanti dei cani di ogni dove nella più grande comunità che il mondo abbia mai conosciuto. Una comunità che starà al nostro fianco, per i nostri cani e per le generazioni a venire — per le persone che non hanno paura di ammettere che un cane non è solo un animale, ma un essere che ci rende esseri umani migliori.',
  'about.crawl.p5':
    'Proprio ora inizia il viaggio verso il primo traguardo — creare 1 000 000 di Heroglyph. E tu puoi farne parte. Perché gli unici abbastanza folli da credere di poter cambiare il mondo sono quelli che lo fanno.',
  'about.crawl.p6': 'Crediamo nel cane.',

  // ── /about — timeline (5 milestones) ──
  'about.timeline.heading': 'La Storia di Dogypt',
  'about.milestone.1.year': '2017',
  'about.milestone.1.tag': 'Il Canile',
  'about.milestone.1.title': 'Tesoro nel Canile',
  'about.milestone.1.body':
    'Un cane nero che nessuno voleva aspettava dietro la recinzione di un canile. Il suo nome divenne Hekthor. Adottarlo non fu un salvataggio — fu l\'inizio di tutto.',
  'about.milestone.2.year': '2018',
  'about.milestone.2.tag': 'Il Legame',
  'about.milestone.2.title': 'Un Legame per Sempre',
  'about.milestone.2.body':
    'Mi ha trascinato attraverso il tratto più difficile della mia vita senza dire una sola parola. Ogni amante dei cani lo sa — ti sostengono proprio quando stai cadendo.',
  'about.milestone.3.year': '2019',
  'about.milestone.3.tag': 'Il Viaggio',
  'about.milestone.3.title': 'La Camminata che Divenne un Libro',
  'about.milestone.3.body':
    'Insieme abbiamo attraversato la Slovacchia — 42 giorni, 800 chilometri, una promessa silenziosa. Quella strada è diventata un libro: „Cesta s Hrdinom" — La Strada con un Eroe.',
  'about.milestone.4.year': '2022',
  'about.milestone.4.tag': 'Il Nome',
  'about.milestone.4.title': 'Una Nazione di Amanti dei Cani',
  'about.milestone.4.body':
    'Piramidi, misticismo, la gloria eterna dell\'Egitto — l\'umanità ne è incantata da millenni. Lega tutto questo all\'amore infinito di un cane e ottieni DOGYPT. Ho sigillato l\'idea all\'Expo Dubai 2022, vestito da faraone.',
  'about.milestone.5.year': 'Ora',
  'about.milestone.5.tag': 'Dogypt',
  'about.milestone.5.title': 'Il Viaggio Inizia con Te',
  'about.milestone.5.body':
    'DOGYPT è un movimento per tutti coloro la cui vita è stata cambiata da un cane. Costruito sul legame più antico e sincero della Terra. Hekthor è il fondatore #1. Il prossimo sei tu.',

  // ── /about — outro + reel ──
  'about.outro.quoteLead': 'Non è Mai Stato',
  'about.outro.quoteTail': '"Solo un Cane."',
  'about.outro.body':
    'Conosci già quella sensazione — che un cane non è qualcosa che possiedi, è <strong>qualcuno che ami</strong>. Ora immagina quell\'amore organizzato, connesso, <strong>abbastanza potente da cambiare le cose.</strong> Ed è per questo che esiste <strong>DOGYPT</strong>.',
  'about.outro.name1': 'Matej',
  'about.outro.and': 'e',
  'about.outro.name2': 'Hekthor',
  'about.outro.cta': 'Diventa Dogizio',
  'about.reel.prev': 'Foto precedente',
  'about.reel.next': 'Foto successiva',

