  'entry.criteria.theology.title': 'Teologia',
  'entry.criteria.theology.body': 'Migliore amico, guardiano, maestro, compagno in ogni avventura. Il cane dona amore senza condizioni — e camminargli accanto ci rende più umani.',
  'entry.criteria.canon.title': 'Canone',
  'entry.criteria.canon.body': 'Ogni fede ha le sue scritture. Il nostro è il DOGMA: il nostro legame con il cane scritto in dodici capitoli, da leggere gratis su dogma.dogypt.com.',
  'entry.criteria.community.title': 'Comunità',
  'entry.criteria.community.body': 'Siamo amanti dei cani con uno scopo. Da soli, ognuno di noi può cambiare poco — insieme, la nostra forza non ha limiti.',
  'entry.criteria.symbol.title': 'Simbolo',
  'entry.criteria.symbol.body': 'Ogni fede ha il suo segno. Il nostro è l\'Heroglyph: un segno sacro unico per ogni cane, comprensibile in ogni lingua, ovunque.',
  'entry.criteria.ritual.title': 'Rito',
  'entry.criteria.ritual.body': 'La passeggiata. Terapia quotidiana che tiene in forma corpo e mente — e anche l\'anima. Il rito più antico che già osserviamo senza che nessuno ce lo dica.',
  'entry.criteria.vision.title': 'Visione',
  'entry.criteria.vision.body': 'Elevare il legame tra uomo e cane — e battersi per il rispetto e la vita migliore che ogni cane merita.',
