  "heroglyph.flow.more.ainubis.d": "La nostra IA personalizzata, il tuo aiutante e mentore. Conosce il tuo cane a menadito. Impara dalle sue fonti, consultale e aggiungi i tuoi materiali e la tua esperienza.",
  "heroglyph.flow.more.ainubis.t": "AINUBIS",
  "heroglyph.flow.more.cause.d": "DOGYPT semplifica la vita agli amanti dei cani, ma unisce anche le persone di buon cuore e aiuta i cani in difficoltà, in modo trasparente. Anche il fondatore di DOGYPT, HEKTHOR, viene da un canile.",
