  "heroglyph.flow.more.close": "Chiudi",
  "heroglyph.flow.more.dogid.d": "Il profilo completo del tuo cane in un unico posto. Tutto ciò che compili, il nostro AINUBIS lo mette a frutto. Una comoda «pagella» sempre a portata di mano, per esempio dal veterinario.",
  "heroglyph.flow.more.dogid.t": "DOG ID",
  "heroglyph.flow.more.dogtrip.d": "Avventure dog friendly da tutto il mondo in un unico posto. Aggiungi la tua gita preferita e condividila con il branco. Lasciati ispirare dagli altri, raccogli punti, badge e livelli.",
