  "heroglyph.flow.more.glyph.d": "Un simbolo unico che rappresenta alla perfezione il tuo cane. Un linguaggio universale pensato per unire gli amanti dei cani. La tua chiave per DOGYPT.",
  "heroglyph.flow.more.glyph.t": "HEROGLYPH",
  "heroglyph.flow.more.money.d": "Di ogni €11, €5 vanno allo sviluppo, €3 alla comunità, €2 al salvataggio dei cani e €1 alla ciotola di Hekthor. Ogni spesa sarà documentata e pubblica.",
