  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. All'interno del branco: cosa vedono gli altri Membri",
  "privacy.s12.body": "L'articolo 3 descrive il GodsGrid pubblico. All'interno del branco — l'area riservata ai membri — gli altri Membri collegati vedono di più: il tuo nome, il tuo numero dogiziano, il nome e la foto del tuo cane, gli attributi che hai inserito per il tuo cane, le gite che hai registrato o annunciato, le tue valutazioni e i commenti, e tutto ciò che hai scritto sul tuo profilo. Non vedono il tuo indirizzo e-mail, il tuo indirizzo postale, i tuoi dati di pagamento né i tuoi messaggi con chiunque altro. Quando annunci una gita come aperta, il percorso, la data e il tuo cane diventano visibili a ogni Membro, che può chiedere di unirsi — questo è il significato di annunciarla. Una gita che mantieni privata è visibile solo a te e alle persone che vi partecipano già. Scegli tu quale delle due opzioni applicare, e puoi cambiarla in qualsiasi momento.",
  "privacy.s13.title": "13. Messaggi e segnalazioni",
  "privacy.s13.body": "I messaggi privati tra Membri sono archiviati nel nostro database (Supabase) affinché le conversazioni sopravvivano tra una sessione e l'altra. Base giuridica: art. 6(1)(b) del GDPR — fanno parte dell'iscrizione che hai pagato. Non li leggiamo di routine e non li usiamo mai per pubblicità o profilazione. Apriamo una conversazione solo quando viene segnalata, quando indaghiamo su un abuso specifico o un incidente di sicurezza, oppure quando lo richiede la legge. Una segnalazione registra il motivo che hai scelto, la tua nota facoltativa e un riferimento a ciò che hai segnalato — non una copia separata. Il blocco viene registrato come una coppia di identificativi dei membri. Se elimini il tuo account, i tuoi messaggi se ne vanno con esso; la copia nel thread dell'altra persona resta, mostrata come proveniente da un membro rimosso, perché quella conversazione appartiene anche a lei.",
  "terms.s12.title": "12. Il contenuto che pubblichi",
  "terms.s12.body": "Oltre al tuo HEROGLYPH, puoi pubblicare contenuti all'interno del branco: foto delle gite, percorsi e luoghi, descrizioni delle gite, valutazioni, commenti e domande, e tutto ciò che scrivi sul tuo profilo. Quando contrassegni una gita come percorsa, gli altri Membri vedono il tuo nome e i cani che l'hanno percorsa con te. Resti proprietario di tutto ciò che pubblichi. Pubblicandolo, concedi a DOGYPT s.r.o. una licenza mondiale, gratuita e non esclusiva per archiviare, mostrare e adattare quel contenuto allo scopo di gestire e promuovere il Servizio — per esempio mostrando la tua foto della gita sulla mappa, in un elenco di gite o su una scheda di condivisione. La licenza dura finché il contenuto è sul Servizio; rimuovendo il contenuto o il tuo account essa termina, salvo per i backup, che scadono secondo il loro ciclo normale. Non vendiamo il tuo contenuto e non lo concediamo in licenza a nessun altro per un uso proprio. Pubblica solo ciò che hai il diritto di pubblicare — incluse le foto scattate da altri e le persone riconoscibili in esse.",
  "terms.s13.title": "13. Messaggi tra Membri",
  "terms.s13.body": "I Membri possono scriversi direttamente. I messaggi sono privati tra i partecipanti — non li leggiamo di routine e non li usiamo mai per pubblicità. Sono archiviati sui nostri server affinché la conversazione sia ancora lì al tuo ritorno, e possiamo leggere una conversazione in tre casi: quando qualcuno la segnala, quando indaghiamo su un abuso specifico o un incidente di sicurezza, oppure quando lo richiede la legge. Puoi bloccare un altro Membro in qualsiasi momento; il blocco è immediato e vale in entrambe le direzioni. Tratta i messaggi come qualsiasi conversazione online — non inviare dati di pagamento, password o documenti che non vorresti vedere archiviati.",
  "terms.s14.title": "14. Segnalazioni e moderazione",
  "terms.s14.body": "Profili, gite e conversazioni possono essere segnalati. Una segnalazione arriva a noi e viene letta da una persona — oggi è il fondatore, Matej Stacho. Il nostro obiettivo è esaminare ogni segnalazione entro 7 giorni. In base a ciò che troviamo, possiamo non fare nulla, rimuovere il contenuto, avvisare il Membro, limitare ciò che può pubblicare, oppure chiudere il suo account. Se interveniamo sul tuo contenuto, te ne spiegheremo il motivo via e-mail, e potrai rispondere e contestare. Possiamo anche rimuovere contenuti di nostra iniziativa quando violano l'articolo 7. Un abuso deliberato o ripetuto — molestie, spam, gite false, contenuti che coinvolgono minori — comporta la chiusura dell'account senza ulteriori avvisi.",
