  "pack.cal.life.recSince": "dal {year}",
  "pack.cal.life.tip.weight.title": "Restare snello è l'unica cosa provata",
  "pack.cal.life.tip.weight.body": "Di tutto ciò che puoi fare per un cane, una cosa ha la prova più solida sulla durata della vita: non lasciarlo ingrassare. La differenza tra un cane snello e uno leggermente sovrappeso si misura in anni, non in mesi. Dovresti poter sentire le costole senza premere.",
  "pack.cal.life.tip.move.title": "Movimento su terreno vero, non un giro del palazzo",
  "pack.cal.life.tip.move.body": "Un terreno irregolare mantiene attivi articolazioni, muscoli e mente. Ogni gita che registri diventa una settimana scura su questa griglia — e le settimane scure sono l'unica cosa che puoi davvero influenzare.",
  "pack.cal.life.tip.food.title": "Un cibo che il cane riconosce come cibo",
  "pack.cal.life.tip.food.body": "Meno passaggi ci sono tra l'ingrediente grezzo e la ciotola, meno cose possono andare storte lungo la strada. Le crocchette non sono un peccato, ma non sono nemmeno una dieta — sono una scorciatoia.",
  "pack.cal.life.tip.chem.title": "Chimica solo quando è davvero necessaria",
  "pack.cal.life.tip.chem.body": "Gli antiparassitari tutto l'anno, l'anestesia per comodità e gli antibiotici «per sicurezza» sono decisioni, non routine. Chiediti, per ciascuno: cosa succede se lo salto? Dove la risposta è «niente», saltalo.",
  "pack.cal.life.tip.stress.title": "Il riposo conta quanto il movimento",
  "pack.cal.life.tip.stress.body": "Un cane sempre in allerta brucia il corpo dall'interno. Un sonno indisturbato, una giornata prevedibile e la calma dopo lo sforzo non sono pigrizia — sono le ore in cui il corpo si ripara.",
  "pack.cal.life.tip.protocol.title": "Un protocollo invece di una corsa nel panico dal veterinario",
  "pack.cal.life.tip.protocol.body": "Sverminazione, coprologia e analisi del sangue hanno le loro finestre nel calendario. Un cane a cui controlli il sangue due volte all'anno non viene curato — viene tenuto avanti.",
  "pack.cal.life.tip.joints.title": "Le articolazioni si affrontano PRIMA che comincino a far male",
  "pack.cal.life.tip.joints.body": "Il tuo cane è ora nella fascia senior. La cura articolare ha la sua finestra nel calendario da novembre — non perché zoppica, ma perché non debba mai farlo.",
