  "pack.hero.popStatusEyebrow": "Status",
  "pack.hero.popPawtner1": "Pawtner è la tua posizione nel branco — sei il compagno di un cane per cui hai creato un HEROGLYPH. Senza heroglyph, non sei un Dogizio.",
  "pack.hero.rolePack": "Branco",
  "pack.hero.roleDog": "Cane",
