  "pack.nature.bal.earth.excess.edema": "Gonfiore che lascia il segno del dito",
  "pack.nature.bal.earth.excess.sticky-mucous": "Muco vischioso",
  "pack.nature.bal.earth.excess.appetite": "Appetito che oscilla su e giù",
