  "pack.nature.ans.no": "No",
  "pack.network.ads.body": "Gli annunci pagati sono un modo molto inefficiente per trovare nuovi amanti dei cani — e un modo di buttare i nostri soldi alle grandi aziende. Funziona molto meglio premiare direttamente i membri del movimento per essere attivi. C'è un ma: <strong style=\"font-weight:600\">funziona davvero solo se tu esci e parli di noi alle persone intorno a te</strong> :)",
  "pack.network.ads.header": "Perché così?",
