  "pack.network.capped.none": "Nessuna devozione da questo — i tuoi regali pareggiano già tutto ciò che hai vissuto. I BONES passano comunque. <i>Il denaro raddoppia gli anni, non li sostituisce mai.</i>",
  "pack.network.capped.room": "Limitato a <b style=\"color:#2a1608\">{room}</b> — un regalo può solo pareggiare quello che hai vissuto ({lived} di devozione finora). I BONES passano comunque; l'onore aspetta i giorni.",
  "pack.network.chainFirstInvite": "il tuo primo invito",
