  "pack.network.copyLinkAria": "Copia il link di invito",
  "pack.network.devotionWord": "devozione",
  "pack.network.emptyLine": "Ancora nessuno — il primo nome qui sarà l'inizio della tua linea.",
  "pack.network.eyebrow": "DOGYPT cresce grazie a te",
  "pack.network.generatingLink": "Generazione del tuo link…",
  "pack.network.linkFailed": "Impossibile caricare il tuo link di invito.",
  "pack.network.linkRetry": "Riprova",
  "pack.network.groupDirect": "diretto",
  "pack.network.groupTheirBrings": "i loro inviti",
  "pack.network.inLine": "Nella tua linea",
  "pack.network.info.bones.body": "I BONES sono la valuta interna di DOGYPT — un nome giocoso per una cosa reale. Un cane paga in ossa; anche noi. Li <b>guadagni</b> portando amanti dei cani nel branco e facendo avanzare il movimento, e li <b>spendi</b> dentro DOGYPT: sostenendo raccolte per i canili, ottenendo merch, e più avanti pagando altri Dogizi per quello che creano. <b>{n} BONES = 1 €.</b>",
  "pack.network.info.bones.cap": "Cosa sono i BONES?",
  "pack.network.info.why.body": "Un movimento di questa dimensione non si può comprare — nessun budget raggiunge un estraneo come un Dogizio raggiunge un amico. Quindi il branco mette la ricompensa dove è la portata: con te. Quando qualcuno si unisce tramite il tuo link ricevi <b>{l1} BONES</b>; quando porta qualcuno a sua volta, ricevi altri <b>{l2}</b>. Ogni Dogizio che diffonde la parola non è un venditore — è un missionario, e onoriamo questo lavoro.",
  "pack.network.info.why.cap": "Perché te lo chiediamo",
  "pack.network.intro": "Un movimento cresce solo quando i suoi membri portano il messaggio e portano nuove persone. Quindi te lo chiediamo direttamente: <strong style=\"color:#2a1608;font-weight:600\">invita gli amanti dei cani che conosci</strong>. Ecco esattamente come funziona.",
  "pack.network.inviteLinkHeader": "Il tuo link di invito",
  "pack.network.listSummary": "{n} persone · {b} BONES guadagnati",
  "pack.network.noBonesYetHint": "Ancora nessun BONES — invita prima qualcuno.",
  "pack.network.noOneYet": "ancora nessuno",
  "pack.network.openWallet": "Apri il portafoglio",
  "pack.network.send.grow.lede": "Questo finanzia quello che il branco costruisce dopo.",
