  "pack.network.step1Title": "Condividi il tuo link",
  "pack.network.step2Body": "Se qualcuno crea un <strong style=\"color:#2a1608;font-weight:600\">Heroglyph</strong> tramite il tuo link, ricevi <strong style=\"color:#2a1608;font-weight:600\">{l1} BONES</strong>. Se quel membro porta a sua volta qualcuno, lui riceve {l1} e <strong style=\"color:#2a1608;font-weight:600\">tu ricevi altri {l2}</strong>.",
